-- Restrict identity columns from public Data API reads. Admin details use audited RPCs.
REVOKE SELECT ON public.posts FROM anon, authenticated;
GRANT SELECT(id,pseudonym,community,title,body,post_type,progress,expires_at,is_deleted,author_deleted,admin_removed,created_at) ON public.posts TO anon,authenticated;
REVOKE SELECT ON public.comments FROM anon,authenticated;
GRANT SELECT(id,post_id,pseudonym,body,is_deleted,admin_removed,created_at) ON public.comments TO anon,authenticated;
REVOKE SELECT ON public.reactions FROM anon,authenticated;
GRANT SELECT(id,post_id,kind,created_at) ON public.reactions TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.reaction_state(_post uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('kind',r.kind,'mine',r.user_id=auth.uid())),'[]'::jsonb) FROM public.reactions r WHERE r.post_id=_post AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_post AND NOT (p.is_deleted OR p.author_deleted OR p.admin_removed) AND (p.expires_at IS NULL OR p.expires_at>now())) $$;
CREATE OR REPLACE FUNCTION public.toggle_reaction(_post uuid,_kind text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR public.is_banned(auth.uid()) OR _kind NOT IN ('hear_you','me_too','strength') OR NOT EXISTS(SELECT 1 FROM public.posts WHERE id=_post AND NOT(is_deleted OR author_deleted OR admin_removed) AND (expires_at IS NULL OR expires_at>now())) THEN RAISE EXCEPTION 'Reaction unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.reactions WHERE post_id=_post AND user_id=auth.uid() AND kind=_kind) THEN DELETE FROM public.reactions WHERE post_id=_post AND user_id=auth.uid() AND kind=_kind; ELSE INSERT INTO public.reactions(post_id,user_id,kind) VALUES(_post,auth.uid(),_kind); END IF; END $$;
CREATE OR REPLACE FUNCTION public.my_space() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('pseudonym',p.pseudonym,'joined',p.created_at,'posts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'body',s.body,'progress',s.progress,'post_type',s.post_type,'created_at',s.created_at,'community',s.community) ORDER BY s.created_at DESC),'[]'::jsonb) FROM public.posts s WHERE s.author_id=auth.uid() AND NOT(s.is_deleted OR s.author_deleted OR s.admin_removed)),'comments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'post_id',c.post_id,'body',c.body,'created_at',c.created_at) ORDER BY c.created_at DESC),'[]'::jsonb) FROM public.comments c WHERE c.author_id=auth.uid() AND NOT(c.is_deleted OR c.admin_removed)),'supported',(SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('id',s.id,'title',s.title,'pseudonym',s.pseudonym)),'[]'::jsonb) FROM public.reactions r JOIN public.posts s ON s.id=r.post_id WHERE r.user_id=auth.uid() AND NOT(s.is_deleted OR s.author_deleted OR s.admin_removed) AND (s.expires_at IS NULL OR s.expires_at>now())),'support_received',(SELECT count(*) FROM public.reactions r JOIN public.posts s ON s.id=r.post_id WHERE s.author_id=auth.uid())) FROM public.profiles p WHERE p.id=auth.uid() $$;
CREATE OR REPLACE FUNCTION public.owner_post_action(_id uuid,_action text,_progress text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR _action NOT IN ('delete','progress') OR NOT EXISTS(SELECT 1 FROM public.posts WHERE id=_id AND author_id=auth.uid() AND NOT(is_deleted OR author_deleted OR admin_removed)) THEN RAISE EXCEPTION 'Post unavailable'; END IF; IF _action='delete' THEN UPDATE public.posts SET author_deleted=true WHERE id=_id; ELSIF _progress IN ('carrying','working','let_go') THEN UPDATE public.posts SET progress=_progress WHERE id=_id; ELSE RAISE EXCEPTION 'Invalid progress'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.admin_open_user(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_id) THEN RAISE EXCEPTION 'User not found'; END IF; INSERT INTO public.admin_actions(admin_id,action,target_type,target_id) VALUES(auth.uid(),'open_user','profile',_id); SELECT jsonb_build_object('profile',(SELECT to_jsonb(p) FROM public.profiles p WHERE p.id=_id),'posts',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.created_at DESC),'[]'::jsonb) FROM public.posts s WHERE s.author_id=_id),'comments',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.created_at DESC),'[]'::jsonb) FROM public.comments c WHERE c.author_id=_id),'reactions',(SELECT coalesce(jsonb_agg(jsonb_build_object('post_id',r.post_id,'kind',r.kind,'created_at',r.created_at)),'[]'::jsonb) FROM public.reactions r WHERE r.user_id=_id),'reports',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) FROM public.reports r WHERE r.reporter_id=_id),'conversations',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'status',c.status,'created_at',c.created_at)),'[]'::jsonb) FROM public.conversations c WHERE c.sender_id=_id OR c.recipient_id=_id)) INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.admin_list_conversations() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.has_role(auth.uid(),'admin') THEN coalesce(jsonb_agg(jsonb_build_object('id',c.id,'status',c.status,'created_at',c.created_at,'sender',a.pseudonym,'sender_email',a.email,'recipient',b.pseudonym,'recipient_email',b.email) ORDER BY c.updated_at DESC),'[]'::jsonb) ELSE '[]'::jsonb END FROM public.conversations c LEFT JOIN public.profiles a ON a.id=c.sender_id LEFT JOIN public.profiles b ON b.id=c.recipient_id $$;
CREATE OR REPLACE FUNCTION public.admin_open_conversation(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF NOT EXISTS(SELECT 1 FROM public.conversations WHERE id=_id) THEN RAISE EXCEPTION 'Conversation not found'; END IF; INSERT INTO public.admin_actions(admin_id,action,target_type,target_id) VALUES(auth.uid(),'open_conversation','conversation',_id); SELECT jsonb_build_object('conversation',jsonb_build_object('id',c.id,'status',c.status,'sender',a.pseudonym,'sender_email',a.email,'recipient',b.pseudonym,'recipient_email',b.email),'messages',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'body',m.body,'sender',CASE WHEN m.sender_id=c.sender_id THEN a.pseudonym ELSE b.pseudonym END,'created_at',m.created_at,'admin_removed',m.admin_removed) ORDER BY m.created_at),'[]'::jsonb) FROM public.messages m WHERE m.conversation_id=c.id)) INTO result FROM public.conversations c LEFT JOIN public.profiles a ON a.id=c.sender_id LEFT JOIN public.profiles b ON b.id=c.recipient_id WHERE c.id=_id; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.admin_moderate(_kind text,_id uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR _id IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF _kind='user' AND _action IN ('ban','unban') THEN UPDATE public.profiles SET is_banned=(_action='ban') WHERE id=_id; ELSIF _kind='post' AND _action='remove' THEN UPDATE public.posts SET admin_removed=true WHERE id=_id; ELSIF _kind='comment' AND _action='remove' THEN UPDATE public.comments SET admin_removed=true WHERE id=_id; ELSIF _kind='message' AND _action='remove' THEN UPDATE public.messages SET admin_removed=true WHERE id=_id; ELSIF _kind='conversation' AND _action='close' THEN UPDATE public.conversations SET status='closed' WHERE id=_id; ELSE RAISE EXCEPTION 'Invalid action'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'Target not found'; END IF; INSERT INTO public.admin_actions(admin_id,action,target_type,target_id) VALUES(auth.uid(),_action,_kind,_id); END $$;
REVOKE ALL ON FUNCTION public.reaction_state(uuid),public.toggle_reaction(uuid,text),public.my_space(),public.owner_post_action(uuid,text,text),public.admin_open_user(uuid),public.admin_list_conversations(),public.admin_open_conversation(uuid),public.admin_moderate(text,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reaction_state(uuid) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.toggle_reaction(uuid,text),public.my_space(),public.owner_post_action(uuid,text,text),public.admin_open_user(uuid),public.admin_list_conversations(),public.admin_open_conversation(uuid),public.admin_moderate(text,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.read_conversation(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL OR NOT public.is_chat_member(_id,auth.uid()) THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; INSERT INTO public.conversation_reads(conversation_id,user_id,last_read_at) VALUES(_id,auth.uid(),now()) ON CONFLICT(conversation_id,user_id) DO UPDATE SET last_read_at=excluded.last_read_at; SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'body',CASE WHEN m.admin_removed THEN '[Removed by admin]' ELSE m.body END,'mine',m.sender_id=auth.uid(),'is_request',m.is_request,'created_at',m.created_at) ORDER BY m.created_at),'[]'::jsonb) INTO result FROM public.messages m WHERE m.conversation_id=_id; RETURN result; END $$;